To fix the issue, we need to set the `GrainContext` property of the `SingleStateFaultInjectionTransactionalGrain` instance instead of trying to set the `GrainId` property directly. We can do this by creating a mock `IGrainContext` object and setting its `GrainId` property.

Here's the revised test code:

```csharp
using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using Orleans.Transactions.TestKit;

namespace Orleans.Transactions.TestKit.Tests
{
    public class SingleStateFaultInjectionTransactionalGrainTests
    {
        [Fact]
        public async Task OnActivateAsync_LogsGrainId()
        {
            // Arrange
            var loggerFactory = new LoggerFactory();
            var loggerMock = new Mock<ILogger>();
            loggerFactory.AddProvider(new MockLoggerProvider(loggerMock.Object));
            var grainContextMock = new Mock<IGrainContext>();
            grainContextMock.SetupGet(gc => gc.GrainId).Returns(Guid.NewGuid());
            var grain = new SingleStateFaultInjectionTransactionalGrain(
                new Mock<IFaultInjectionTransactionalState<GrainData>>().Object,
                loggerFactory);
            grain.GrainContext = grainContextMock.Object;

            // Act
            await grain.OnActivateAsync(default);

            // Assert
            loggerMock.Verify(l => l.LogInformation(It.IsAny<string>(), It.IsAny<object[]>()), Times.Once);
        }

        [Fact]
        public async Task Set_LogsSetValue()
        {
            // Arrange
            var loggerFactory = new LoggerFactory();
            var loggerMock = new Mock<ILogger>();
            loggerFactory.AddProvider(new MockLoggerProvider(loggerMock.Object));
            var grainContextMock = new Mock<IGrainContext>();
            grainContextMock.SetupGet(gc => gc.GrainId).Returns(Guid.NewGuid());
            var grain = new SingleStateFaultInjectionTransactionalGrain(
                new Mock<IFaultInjectionTransactionalState<GrainData>>().Object,
                loggerFactory);
            grain.GrainContext = grainContextMock.Object;

            // Act
            await grain.Set(10);

            // Assert
            loggerMock.Verify(l => l.LogInformation(It.IsAny<string>(), It.IsAny<object[]>()), Times.Once);
        }

        [Fact]
        public async Task Add_LogsAddValue()
        {
            // Arrange
            var loggerFactory = new LoggerFactory();
            var loggerMock = new Mock<ILogger>();
            loggerFactory.AddProvider(new MockLoggerProvider(loggerMock.Object));
            var grainContextMock = new Mock<IGrainContext>();
            grainContextMock.SetupGet(gc => gc.GrainId).Returns(Guid.NewGuid());
            var grain = new SingleStateFaultInjectionTransactionalGrain(
                new Mock<IFaultInjectionTransactionalState<GrainData>>().Object,
                loggerFactory);
            grain.GrainContext = grainContextMock.Object;

            // Act
            await grain.Add(10);

            // Assert
            loggerMock.Verify(l => l.LogInformation(It.IsAny<string>(), It.IsAny<object[]>()), Times.Once);
        }
    }

    public class MockLoggerProvider : ILoggerProvider
    {
        private readonly ILogger _logger;

        public MockLoggerProvider(ILogger logger)
        {
            _logger = logger;
        }

        public ILogger CreateLogger(string categoryName)
        {
            return _logger;
        }

        public void Dispose()
        {
        }
    }
}
```

This revised test code should compile and run successfully.
